import { BaseClassSrvc } from '@_core/__base';
import { ChangeDetectionStrategy, Component, Input, ViewEncapsulation } from '@angular/core';

@Component({
  standalone: false,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'tbl-filter-template',
  templateUrl: './tbl-filter-template.html',
  styles: `
    .mat-expansion-panel-body {
      padding: 3px !important;
      // padding-right: px !important;
    }
  `,
})
export class TblFilterTemplate extends BaseClassSrvc {
  @Input() filterSystemShow = false;
  @Input() filterDefaultShow = false;
  @Input() filterAdvanceShow = false;

  public resetFilters(){
    this._template.lb.filterSystem.reset();
    this._template.lb.filterDefault.reset();
    this._template.lb.filterAdvance.reset();
    this._template.lb.fresh();
  }
}
