import { Component, Input } from '@angular/core';
import { BaseSetControl } from '../1.set-Control';

import { ViewEncapsulation, ChangeDetectionStrategy } from '@angular/core';
import { SelectOptions } from '@_core/_client';
@Component({
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  standalone: false,
  selector: 'ctrl-opt-radio',
  templateUrl: './opt-radio.html',
  styles: `
    .ele-wrap {
      background-color: var(
        --mat-form-field-filled-container-color,
        var(--mat-sys-surface-variant)
      );
      height: 57px;
      margin-top: 4px;
      border-radius: 5px 5px 0px 0px;
      border-bottom: 1px solid black;
      margin-bottom: 5px;
    }
    mat-error {
      font-size: var(--mat-form-field-subscript-text-size);
    }
  `,
})
// Text Control
export class CtrlOptRadio extends BaseSetControl {
  @Input() listz: SelectOptions[];
}
