import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { BehaviorSubject, Subject } from 'rxjs';
import { BaseSetControl } from './1.set-Control';
import { HttpReq, HttpResOptions, SelectOptions } from '@_core/_client';

@Component({ template: '' })
export class BaseDD_Static extends BaseSetControl implements OnInit {
  @Input() httpReq: Partial<HttpReq> = {};
  @Input() httpResOpts: Partial<HttpResOptions> = {};
  @Input() listz: Partial<Listz> = {};

  @Output('changeEvent') changeEvents = new EventEmitter<SelectOptions>();
  // constructor() {
  //  super();
  //  this._cdr = inject(ChangeDetectorRef);
  // }
  override ngOnInit(): void {
    super.ngOnInit();
    this.setDefaultSettingsList();
    this.setListStatic()

  }
  setDefaultSettingsList(){
    this.listz = {
      listView: new BehaviorSubject<SelectOptions[]>([]),
      ...this.listz,
    }
  }
  setListStatic(){
    if (this.listz?.listStatic) {
      this.setListView(this.listz.listStatic);
    }
  }
  setListView(list: SelectOptions[]) {
    if (list[0].id != null) list.unshift(EmptyOption(this.ctrl.lbl));
    this.listz.listView.next(list);
    // this._cdr.detectChanges();
  }
  public changeEvent(itm, event) {
    console.log(itm, event);
    this.changeEvents?.emit(itm);
  }

  setControlAfterDataFetched(records: SelectOptions[]){
    // Handling Control Behaviour
    const control = this.ctrl.control;
    if (records.length == 0) {
      control.patchValue(null);
    } else if (records.length == 1) {
      control.patchValue(records[0].id);
    } else if (records.length > 1) {
      records.forEach((item) => {
        if (item.id == control?.value) {
          control.patchValue(control?.value);
          control.updateValueAndValidity();
        }
      });
    }
  }

}

export function EmptyOption(lbl: string): SelectOptions {
  return {
    id: null,
    name: 'Please Select ' + lbl,
    isSelected: false,
    status: null,
  };
}
export interface Listz {
  listStatic: SelectOptions[];
  listView: Subject<SelectOptions[]>;
  listSearch: SelectOptions[];
  state: boolean;
  isLoading: boolean;
}
