import { BaseClassProp } from '@_core/__base';
import { CONTROL_HOST_CSS_CLASS } from '@_core/_form';
import { Component, EventEmitter, HostBinding, Input, Output, SimpleChanges } from '@angular/core';
import { FormControl, FormGroup } from '@angular/forms';
import { debounceTime } from 'rxjs';

@Component({ template: '' })
export class BaseSetControl extends BaseClassProp  {
  @Input('class')
  @HostBinding('class')
  public classz = CONTROL_HOST_CSS_CLASS;

  // @HostBinding('style')
  // readonly stylez = AsterikStyle;


  public _lang: string;
  @Input() public ctrl: ControlzConfig  = {}
  @Output() public valueChanges: EventEmitter<string> = new EventEmitter();

  @Output() public Blur: EventEmitter<any> = new EventEmitter();


  ngOnInit(): void {
    this._lang = this._translate.currentLang;
    this.setDefaultSettingsControl();
    if (!this.ctrl.control) {
      this.set_Control(this.ctrl.group, this.ctrl.groupName, (group) => {
        this.ctrl.control = group?.get(this.ctrl.field) as FormControl;
        this.handleAfterSetControl();
      });
    } else {
      this.handleAfterSetControl();
      this.ctrl.field
    }
    const subs = this._translate.onLangChange
      .pipe(debounceTime(100))
      .subscribe((lng) => {
        this._lang = lng.lang;
        (this.ctrl.control?.statusChanges as EventEmitter<any>)?.emit(
          this.ctrl.control.status
        );
      });
    this.subscriptionArray.push(subs);

    if (this.ctrl.disabled) this.ctrl.control.disable();

  }
  setDefaultSettingsControl(){
    this.ctrl = {
      lbl: 'Name',
      req:  true,
      control: null,
      field: 'name',
      group: this._fs._form,
      groupName: null,
      disabled: false,
      readonly: false,
      isHide: false,
      type: 'text',
      ...this.ctrl
    }
  }
  // For Setting (Self, Parent & Child) Controls
  set_Control(
    group: FormGroup,
    groupName: string,
    setControlAction: (group: FormGroup) => void
  ) {
    if (groupName) {
      group = this._fs._form.get(this.ctrl.groupName) as FormGroup;
    } else if (!group && !groupName && !this.ctrl.group) {
      group = this._fs._form as FormGroup;
    } else if (!group && !groupName && this.ctrl.group) {
      group = this.ctrl.group;
    }
    // Without this the this.group won't set
    if (!this.ctrl.group) {
      this.ctrl.group = group;
    }
    if (group) {
      setControlAction(group);
    }
  }
  handleAfterSetControl() {
    this.valueChangesSubscription();
    this.statusChangesSubscription();
    if (this.ctrl.control && !this.ctrl.control?.value) this.ctrl.control?.patchValue(null);
  }

  statusChangesSubscription() {
    const subs = this.ctrl.control?.statusChanges?.subscribe(() => {
      this.ctrl.error = this._vs.handleRequired(this.ctrl.control);
    });
    this.subscriptionArray.push(subs);
  }
  valueChangesSubscription() {
    const subs = this.ctrl.control?.valueChanges?.subscribe((val) => {
      this.valueChanges.emit(val);
    });
    this.subscriptionArray.push(subs);
  }

  FuncBlur($event) {
    this.Blur.emit($event);
  }

  ngOnChanges(changes: SimpleChanges) {
    // if (changes?.disabled?.currentValue != undefined) {
    //   if (this.ctrl.control && changes?.disabled?.currentValue) {
    //     this.ctrl.control.disable();
    //   } else if (this.ctrl.control && !changes?.disabled?.currentValue) {
    //     this.ctrl.control.enable();
    //   }
    // }
  }


}

export interface ControlzConfig extends ControlzParentConfig {
  lbl?: string;
  req?: boolean;
  disabled?: boolean;
  readonly?: boolean;
  isHide?: boolean;
  error?: string;
  hint?:string;
  type?: 'number' | 'text' | 'select' | 'date' | 'checkbox' | 'radio' | 'textarea';
}
export interface ControlzParentConfig {
  control?: FormControl | null;
  field?: string | null;
  group?: FormGroup;
  groupName?: string | null;
}


